// shape 3  PRISM  CopperBkwall3PV   x1
{
  // Extruded solid, built the way G4ExtrudedSolid expects: the
  // cap polygon lies in x,y and the sweep runs along z, here
  // 150.4000 mm. Nothing about this solid is oblique -- the cap
  // basis u=(0,-1,-0) w=(1,0,-0) and the sweep
  // axis (0, -0, 1) form an orthonormal right-handed
  // frame, and that frame is the placement rotation below.
  std::vector<G4TwoVector> s3_pts = {
      G4TwoVector(0.0000*CLHEP::mm, 0.0000*CLHEP::mm),
      G4TwoVector(0.0000*CLHEP::mm, -17.9605*CLHEP::mm),
      G4TwoVector(482.4406*CLHEP::mm, -500.4012*CLHEP::mm),
      G4TwoVector(500.4012*CLHEP::mm, -500.4012*CLHEP::mm) };
  G4VSolid* s3 = new G4ExtrudedSolid("CopperBkwall3PV", s3_pts,
      150.4000*CLHEP::mm/2.0,
      G4TwoVector(), 1.0, G4TwoVector(), 1.0);
  // CAD colour "medium maroon" -> G4_Cu (a guess: review before use)
  G4Material* mat = findOrBuildMaterial("G4_Cu");
  G4LogicalVolume* s3LV = new G4LogicalVolume(s3, mat, "CopperBkwall3PV");

  {  // solid 9, NX part AI-129788-A_1
    G4RotationMatrix* s3_rot9 = new G4RotationMatrix();
    s3_rot9->rotateAxes(G4ThreeVector(1, 4.07335e-13, -0),
                       G4ThreeVector(2.20817e-32, -5.42101e-20, 1),
                       G4ThreeVector(3.51509e-15, -1, -5.42101e-20));  // x->x y->z z->-y
    new G4PVPlacement(s3_rot9,
        G4ThreeVector(-639.873*CLHEP::mm, -8.268*CLHEP::mm, 722.656*CLHEP::mm),
        s3LV, "CopperBkwall3PV_0", motherLV, false, 0, doSurfaceCheck);
  }
}

